import { ImageSourcePropType } from 'react-native';

// IMPORTANT: These assets are cropped/downsampled ONLY from the FIRST approved Nexus Rush image batch.
// No second-generation/regenerated token or map artwork is used here.
export const CARD_ART_ATLAS: ImageSourcePropType = { uri: 'data:image/jpeg;base64,' };
export const MAP_HORIZONTAL: ImageSourcePropType = { uri: 'data:image/jpeg;base64,' };
export const MAP_VERTICAL: ImageSourcePropType = { uri: 'data:image/jpeg;base64,' };

export const CARD_ART_COORDS: Record<string, { col: number; row: number }> = {
  arcane_apprentice: { col: 0, row: 0 },
  battle_mage: { col: 1, row: 0 },
  frost_weaver: { col: 2, row: 0 },
  arcane_elemental: { col: 3, row: 0 },
  archmage: { col: 4, row: 0 },
  arcane_tower: { col: 0, row: 1 },
  mana_crystal: { col: 1, row: 1 },
  fireball: { col: 2, row: 1 },
  ice_chains: { col: 3, row: 1 },
  translocation: { col: 4, row: 1 },
  squire: { col: 0, row: 2 },
  paladin: { col: 1, row: 2 },
  order_crossbow: { col: 2, row: 2 },
  shield_guardian: { col: 3, row: 2 },
  nexus_knight: { col: 4, row: 2 },
  bastion_champion: { col: 0, row: 3 },
  watch_tower: { col: 1, row: 3 },
  nexus_chapel: { col: 2, row: 3 },
  rally: { col: 3, row: 3 },
  holy_punishment: { col: 4, row: 3 }
};

export function mapBackground(mode: 'horizontal-dual-nexus' | 'vertical-single-nexus') {
  return mode === 'horizontal-dual-nexus' ? MAP_HORIZONTAL : MAP_VERTICAL;
}

export function factionForCard(cardId: string): 'arcane' | 'bastion' {
  return (CARD_ART_COORDS[cardId]?.row ?? 0) < 2 ? 'arcane' : 'bastion';
}